    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    for d in (1,-1):
        for i in range(h-1):
            for j in range(w):
                c=g[i][j]
                if c!=bg and 0<=j+d<w and g[i+1][j+d]==c:
                    x,y=i+1,j+d
                    while 0<=x<h and 0<=y<w and g[x][y]==bg:
                        g[x][y]=c; x+=1; y+=d
    return g
